public class Package : System.ComponentModel.INotifyPropertyChanged { public event System.ComponentModel.PropertyChangedEventHandler PropertyChanged; bool pick; public string DisplayGroup {get{return Group;}} public bool HighRisk {get;set;} public string AiOpinion {get;set;} public bool Pick {get{return pick;}set{if(pick==value)return;pick=value;var changed=PropertyChanged;if(changed!=null)changed(this,new System.ComponentModel.PropertyChangedEventArgs("Pick"));}} public string Name {get;set;} public string Id {get;set;} public string Path {get;set;} public string State {get;set;} public string Risk {get;set;} public string Reason {get;set;} public string Group {get;set;} public string NameSource {get;set;} public bool System {get;set;} public bool IsLauncher {get;set;} }
public partial class TV : Window {
 static string Root=AppDomain.CurrentDomain.BaseDirectory; static string Data=Environment.GetEnvironmentVariable("TVSTUDIO_DATA") ?? System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"XiaZheTengTV","Data");
 string serial=""; bool busy=false; TextBox host,search,path,endpoint,model; PasswordBox key; TextBox log; TextBlock status; StackPanel body; DataGrid grid; List<Package> packages=new List<Package>(); string page="应用管理"; HashSet<string> protect=new HashSet<string>();
 public TV(){InitializeStudio();}
 void Add(Panel panel,string text,Action action){var b=new Button{Content=text,Padding=new Thickness(14,9,14,9),Margin=new Thickness(4),Background=Brushes.White,BorderBrush=(Brush)new BrushConverter().ConvertFrom("#E0E0E5"),Cursor=System.Windows.Input.Cursors.Hand};if(new[]{"连接电视","AI智能分析","全部安装","扫描应用列表","安装此桌面","开始分析","保存配置"}.Contains(text)){b.Tag="Primary";b.Background=AppleAccent();b.Foreground=Brushes.White;b.BorderBrush=Brushes.Transparent;}NormalizeActionButton(b,text);b.ToolTip=ButtonHelp(text);b.Click+=(s,e)=>{try{action();}catch(Exception ex){Report(ex.Message);}};panel.Children.Add(b);}
 void Heading(string title,string sub){body.Children.Add(new TextBlock{Text=title,FontSize=27,FontWeight=FontWeights.Bold,Margin=new Thickness(4,8,0,8)});body.Children.Add(new TextBlock{Text=sub,Foreground=Brushes.Gray,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(4,0,0,16)});}
 void Report(string t){Dispatcher.Invoke(new Action(()=>{log.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+t+Environment.NewLine);log.ScrollToEnd();}));File.AppendAllText(Data+"/activity.log",DateTime.Now+" "+t+Environment.NewLine);}
 async void Run(Func<Task> action){if(busy){Report("任务正在进行，请稍候。");return;}busy=true;cancelRequested=false;try{await action();}catch(OperationCanceledException){Bind();Report("已取消，已完成的结果保留。");}catch(Exception ex){Report("失败："+(ex.Message.IndexOf("unauthorized",StringComparison.OrdinalIgnoreCase)>=0?"电视尚未授权，请在电视上允许这台电脑调试":ex.Message.IndexOf("offline",StringComparison.OrdinalIgnoreCase)>=0?"电视离线，请检查网络并重新连接":ex.Message.IndexOf("refused",StringComparison.OrdinalIgnoreCase)>=0?"连接被拒绝，请检查电视 IP、连接端口及调试开关":ex.Message));}finally{busy=false;cancelRequested=false;cancellableTask=false;}}
 static string Q(string s){if(s.Contains("\"")||s.Contains("\n")||s.Contains("\r"))throw new Exception("参数包含不允许的字符");return "\""+s+"\"";}
 static string Sh(string s){return "'"+s.Replace("'","'\\''")+"'";}
 async Task<string> ProcessRun(string exe,string args,int timeout){return await Task.Run(()=>{var info=new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8,WorkingDirectory=Root};info.EnvironmentVariables["ANDROID_USER_HOME"]=Data+"/adbhome";info.EnvironmentVariables["ANDROID_SDK_HOME"]=Data;info.EnvironmentVariables["HOME"]=Data;Directory.CreateDirectory(Data+"/adbhome");using(var p=Process.Start(info)){var o=p.StandardOutput.ReadToEndAsync();var e=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(timeout)){p.Kill();throw new Exception("命令超时，已停止本次操作");}Task.WaitAll(o,e);string text=o.Result+e.Result;if(p.ExitCode!=0)throw new Exception(text);return text;}});}
 Task<string> Adb(string cmd,bool device=true){if(device&&serial=="")throw new Exception("请先连接电视");return ProcessRun(Root+"adb.exe","-P 15037 "+(device?"-s "+Q(serial)+" ":"")+cmd,180000);}
 Task<string> Shell(string cmd){return Adb("shell "+Q(cmd));}
 void Connect(){string h=host.Text.Trim();if(!Regex.IsMatch(h,@"^[a-zA-Z0-9._-]+(:[0-9]{1,5})?$"))throw new Exception("请输入电视 IP:端口");if(!h.Contains(":"))h+=":5555";Run(async()=>{Report((await Adb("connect "+Q(h),false)).Trim());string state=await ProcessRun(Root+"adb.exe","-P 15037 -s "+Q(h)+" get-state",15000);if(state.Trim()!="device")throw new Exception("电视未授权或离线，请在电视上允许调试");serial=h;RememberDevice();File.WriteAllText(Data+"/host.txt",h);status.Text=(await Shell("getprop ro.product.model")).Trim()+" · "+serial+" · 已连接";await Scan();});}
 void Devices(){Run(async()=>{string s=await Adb("devices",false);var choices=s.Split('\n').Where(x=>Regex.IsMatch(x,@"\sdevice\s*$")).Select(x=>x.Split('\t')[0].Trim()).ToArray();string pick=Prompt("选择设备序列号",choices.Length==1?choices[0]:string.Join("\n",choices));if(pick==null)return;if(!choices.Contains(pick))throw new Exception("请选择列表中的在线设备");serial=pick;RememberDevice();status.Text=pick+" · 已连接";await Scan();});}
 async Task Scan(){string all=await Shell("pm list packages -u -f");string installed=await Shell("pm list packages");string disabled=await Shell("pm list packages -d");var active=new HashSet<string>(installed.Split('\n').Select(x=>x.Trim().Replace("package:","")));var off=new HashSet<string>(disabled.Split('\n').Select(x=>x.Trim().Replace("package:","")));packages=new List<Package>();foreach(string l in all.Split('\n')){var m=Regex.Match(l.Trim(),@"^package:(.*)=([A-Za-z0-9_.]+)$");if(!m.Success)continue;string id=m.Groups[2].Value;packages.Add(new Package{Id=id,Name=id,Path=m.Groups[1].Value,State=!active.Contains(id)?"已卸载":off.Contains(id)?"已停用":"已安装",Risk=IsProtected(id)?"保护":"待分析",Reason=IsProtected(id)?"核心服务、桌面或保护清单":"未验证"});}if(packages.Count==0)throw new Exception("未读取到应用列表，请检查电视是否授权 ADB 及应用管理权限。");usingAi=false;SelectedCategory="全部应用";ApplyMetadata();await RefreshSystemFlags();await RefreshHomes();scannedFor=serial;LoadHistoryEntries();File.WriteAllText(Data+"/scan.json",new JavaScriptSerializer().Serialize(packages));Report("扫描完成："+packages.Count+" 个应用");Show(page);}
 bool IsProtected(string id){return false;}
 void LegacyShow(string p){page=p;body.Children.Clear();Heading(p,"独立 ADB · 全局支持拖入 APK · 操作结果显示在底部");var bar=new WrapPanel();body.Children.Add(bar);
 if(p=="应用管理"||p=="恢复应用"||p=="AI 分析"){
 Add(bar,"刷新扫描",()=>Run(async()=>await Scan()));Add(bar,"深度识别名称",()=>Deep());if(p=="恢复应用"){Add(bar,"恢复勾选",()=>Change("restore"));Add(bar,"从 APK 备份恢复",()=>RestoreBackup());}else {Add(bar,"停用勾选",()=>Change("disable"));Add(bar,"卸载勾选（当前用户）",()=>Change("uninstall"));Add(bar,"备份 APK",()=>Backup());}if(p=="AI 分析"){Add(bar,"配置并分析",()=>Analyze());Add(bar,"选中推荐卸载",()=>{foreach(var a in packages)a.Pick=a.Risk=="推荐卸载"&&!IsProtected(a.Id)&&a.State=="已安装";Bind();});}Add(bar,"导出扫描",()=>Export());Add(bar,"导出勾选方案",()=>ExportProfile());search=new TextBox{Margin=new Thickness(4,10,4,8),Padding=new Thickness(10),ToolTip="搜索包名、名称或风险"};search.TextChanged+=(s,e)=>Bind();body.Children.Add(search);grid=new DataGrid{AutoGenerateColumns=false,Height=340,CanUserAddRows=false,Background=Brushes.White,RowHeight=34,HeadersVisibility=DataGridHeadersVisibility.Column,SelectionMode=DataGridSelectionMode.Extended};grid.Columns.Add(new DataGridCheckBoxColumn{Header="选择",Binding=new System.Windows.Data.Binding("Pick"),Width=45});foreach(string c in new[]{"Name","Id","State","Risk","Reason"})grid.Columns.Add(new DataGridTextColumn{Header=new Dictionary<string,string>{{"Name","应用"},{"Id","包名"},{"State","状态"},{"Risk","判断"},{"Reason","依据"}}[c],Binding=new System.Windows.Data.Binding(c),IsReadOnly=true,Width=c=="Reason"?240:150});body.Children.Add(grid);Bind();return;}
 if(p=="安装与桌面"){Add(bar,"选择 APK（支持多选）",()=>{var d=new OpenFileDialog{Filter="安卓安装包|*.apk",Multiselect=true};if(d.ShowDialog()==true)Install(d.FileNames);});Add(bar,"全部安装",()=>Install(Directory.GetFiles(Root+"apps","*.apk")));foreach(string f in Directory.GetFiles(Root+"Launcher","*.apk")){string apk=f;Add(bar,"安装 "+System.IO.Path.GetFileNameWithoutExtension(f),()=>Install(new[]{apk}));}Add(bar,"打开电视桌面选择",()=>Run(async()=>Report(await Shell("am start -a android.intent.action.MAIN -c android.intent.category.HOME"))));return;}
 if(p=="文件管理"){path=new TextBox{Text="/sdcard/",Margin=new Thickness(4),Padding=new Thickness(9)};body.Children.Add(path);Add(bar,"浏览",()=>Browse());Add(bar,"上传文件",()=>{var d=new OpenFileDialog();if(d.ShowDialog()==true){string dest=RemotePath();Run(async()=>Report(await Adb("push "+Q(d.FileName)+" "+Q(dest))));}});Add(bar,"下载选中文件",()=>Download());Add(bar,"新建文件夹",()=>{string n=Prompt("文件夹名称","");if(string.IsNullOrWhiteSpace(n)||n.IndexOfAny(new[]{'/','\\','\n','\r'})>=0)return;string d=RemotePath()+"/"+n;Run(async()=>{Report(await Shell("mkdir -p "+Sh(d)));await ListFiles();});});Add(bar,"删除选中文件",()=>DeleteFile());grid=new DataGrid{AutoGenerateColumns=true,IsReadOnly=true,Height=340,CanUserAddRows=false};grid.MouseDoubleClick+=(s,e)=>{var r=grid.SelectedItem as RemoteFile;if(r!=null&&r.Type=="目录"){path.Text=RemotePath().TrimEnd('/')+"/"+r.Name;Browse();}};body.Children.Add(grid);return;}
 if(p=="配置与保护"){ShowFolderPage();return;}
 if(p=="设备工具"){Add(bar,"重启电视",()=>{if(Confirm("重启当前电视？"))Run(async()=>{await StopMirror();Report(await Adb("reboot"));});});Add(bar,"好像搞错了？重新再来！",()=>Show("重新再来"));Add(bar,"设备信息",()=>Run(async()=>Report(await Shell("getprop ro.product.manufacturer; getprop ro.product.model; getprop ro.build.version.release; df /sdcard"))));Add(bar,"断开当前连接",()=>{EnsureStreamIdle();Run(async()=>{Report(await Adb("disconnect "+Q(serial),false));serial="";status.Text="未连接";});});Add(bar,"查看日志",()=>Process.Start("notepad.exe",Q(Data+"/activity.log")));}
 }
 bool Confirm(string s){return MessageBox.Show(this,s,"确认操作",MessageBoxButton.YesNo,MessageBoxImage.Warning)==MessageBoxResult.Yes;}
 string Prompt(string title,string initial){var w=new Window{Title=title,Width=650,Height=290,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner};var p=new StackPanel{Margin=new Thickness(20)};ApplyMacChrome(w,p);p.Children.Add(new TextBlock{Text=title,TextWrapping=TextWrapping.Wrap});var t=new TextBox{Text=initial,Margin=new Thickness(0,12,0,10)};p.Children.Add(t);var b=new Button{Content="确定",Padding=new Thickness(12)};p.Children.Add(b);b.Click+=(s,e)=>w.DialogResult=true;return w.ShowDialog()==true?t.Text:null;}
 void Change(string mode){grid.CommitEdit();var rows=VisiblePackages().Where(a=>a.Pick).ToList();if(rows.Count==0)return;if(!ScanReady())throw new Exception("请先扫描当前电视");if(mode!="restore"&&rows.Any(a=>a.State!="已安装"&&a.State!="已停用"))throw new Exception("应用不在当前已安装清单");if(!Confirm("将在 "+serial+" 上"+(mode=="restore"?"恢复":mode=="disable"?"停用":"卸载当前用户的")+rows.Count+" 个应用。\n"+string.Join("\n",rows.Take(12).Select(a=>a.Id))+"\n第三方应用请先备份；数据恢复不作保证。"+(rows.Any(a=>a.Group=="重点审查")?"\n包含重点审查项，可能影响音频、遥控、网络等功能，建议逐项处理。":"")))return;Run(async()=>{BeginUndoBatch(rows,mode);foreach(var a in rows){try{string result;if(mode=="restore"){result=await RestorePackage(a.Id);}else result=await ApplyChange(mode,a.Id);Report(a.Id+": "+result.Trim());RecordChange(mode,a.Id,result);}catch(Exception ex){Report(a.Id+": "+ex.Message);}}await Scan();});}
 async Task<string> RestorePackage(string id){string result="";try{result=await Shell("cmd package install-existing --user 0 "+id);}catch(Exception){result="";}if(result.IndexOf("installed",StringComparison.OrdinalIgnoreCase)<0&&result.IndexOf("Success",StringComparison.OrdinalIgnoreCase)<0)result+=await Shell("pm install-existing --user 0 "+id);result+=await Shell("pm enable --user 0 "+id);return result;} void Install(string[] files){if(files.Any(f=>!File.Exists(f)||!f.EndsWith(".apk",StringComparison.OrdinalIgnoreCase)))throw new Exception("只接受 APK 文件");if(!Confirm("向 "+serial+" 安装 / 覆盖更新 "+files.Length+" 个 APK？"))return;Run(async()=>{foreach(string f in files){try{Report(System.IO.Path.GetFileName(f)+": "+await Adb("install -r "+Q(f)));}catch(Exception ex){Report(ex.Message);}}await Scan();});}
 void RestoreBackup(){var d=new OpenFileDialog{Filter="APK（同一应用分包须一起选中）|*.apk",Multiselect=true,InitialDirectory=Data+"/backups"};if(d.ShowDialog()!=true)return;string[] files=d.FileNames;if(!Confirm("恢复选中的 APK？多选时必须属于同一应用。备份不含应用数据。"))return;Run(async()=>{Report(await Adb((files.Length==1?"install -r ":"install-multiple -r ")+string.Join(" ",files.Select(Q))));await Scan();});} void Backup(){grid.CommitEdit();var rows=VisiblePackages().Where(a=>a.Pick).ToList();Run(async()=>{foreach(var a in rows){string dir=Data+"/backups/"+Regex.Replace(serial,@"[^A-Za-z0-9]","_")+"/"+a.Id;Directory.CreateDirectory(dir);string paths=await Shell("pm path "+a.Id);foreach(string l in paths.Split('\n').Where(x=>x.StartsWith("package:"))){string r=l.Substring(8).Trim();Report(await Adb("pull "+Q(r)+" "+Q(dir+"/"+System.IO.Path.GetFileName(r))));}}Report("APK 备份完成，保存在用户数据目录；分包应用须 install-multiple 恢复。");});}
 void ExportProfile(){grid.CommitEdit();var d=new SaveFileDialog{Filter="包名配置|*.txt",FileName="normal.txt"};if(d.ShowDialog()==true)File.WriteAllLines(d.FileName,packages.Where(a=>a.Pick).Select(a=>a.Id));} void Export(){var d=new SaveFileDialog{FileName="电视扫描.json",Filter="JSON|*.json"};if(d.ShowDialog()==true)File.WriteAllText(d.FileName,new JavaScriptSerializer().Serialize(packages));}
 void Profile(string mode){var d=new OpenFileDialog{Filter="包名方案|*.txt"};if(d.ShowDialog()!=true)return;var ids=new HashSet<string>(File.ReadAllLines(d.FileName).Select(l=>l.Trim()).Where(l=>!l.StartsWith("#")));foreach(var a in packages)a.Pick=ids.Contains(a.Id)&&(a.State=="已安装"||a.State=="已停用");SelectedCategory="全部应用";Show("步骤3");Report(mode+" 方案已匹配，请复核勾选项后执行。");}
 public class RemoteFile{public string Name{get;set;}public string Type{get;set;}}
 string RemotePath(){string p=path.Text.Trim();if(p.Split('/').Any(x=>x=="..")||!p.StartsWith("/")||p.Contains("\n")||p.Contains("\r")||p.Contains("\""))throw new Exception("请输入绝对路径");return p;}
 async Task ListFiles(){string p=RemotePath();string result=await Shell("ls -1ap "+Sh(p));grid.ItemsSource=result.Split('\n').Select(x=>x.TrimEnd('\r')).Where(x=>x!=""&&x!="./"&&x!="../").Select(x=>new RemoteFile{Name=x.TrimEnd('/'),Type=x.EndsWith("/")?"目录":"文件"}).ToList();}
 void Browse(){Run(async()=>await ListFiles());}
 void Download(){var r=grid.SelectedItem as RemoteFile;if(r==null||r.Type=="目录")throw new Exception("请选择文件");var d=new SaveFileDialog{FileName=r.Name};if(d.ShowDialog()==true){string remote=RemotePath().TrimEnd('/')+"/"+r.Name;Run(async()=>Report(await Adb("pull "+Q(remote)+" "+Q(d.FileName))));}}
 void DeleteFile(){var r=grid.SelectedItem as RemoteFile;if(r==null||r.Type=="目录")throw new Exception("仅支持删除单个文件，避免递归误删");string remote=RemotePath().TrimEnd('/')+"/"+r.Name;if(!remote.StartsWith("/sdcard/"))throw new Exception("删除仅允许共享存储 /sdcard 内的文件");if(Confirm("永久删除 "+remote+"？"))Run(async()=>{Report(await Shell("rm -- "+Sh(remote)));await ListFiles();});}
 [STAThread] public static void Main(string[] args){bool created;using(var mutex=new Mutex(true,"Local\\XiaZheTengTVStudio",out created)){if(!created){MessageBox.Show("TV Studio 已运行，请返回现有窗口。");return;}var app=new Application();app.DispatcherUnhandledException+=(s,e)=>{MessageBox.Show(e.Exception.Message);e.Handled=true;};app.Run(new TV());}}
